<template><SilkRoadWorkspace title="数字人营销中心"><template #actions><el-button type="primary" @click="router.push('/digital-human/create')">创建数字人口播</el-button></template><section class="head"><div><span>DIGITAL PRESENTER</span><h1>商品讲解人与品牌口播</h1><p>管理数字人形象、商品讲解视频、品牌口播任务和生成结果。</p></div><el-select v-model="status" clearable placeholder="筛选任务状态" @change="load"><el-option label="全部" value=""/><el-option label="等待中" value="pending"/><el-option label="处理中" value="processing"/><el-option label="已完成" value="completed"/><el-option label="失败" value="failed"/></el-select></section><div v-loading="loading" class="task-grid"><article v-for="task in tasks" :key="task.id"><video v-if="task.video_url" :src="task.video_url" controls/><div v-else class="avatar"><el-icon><UserFilled/></el-icon></div><div><el-tag :type="tone(task.status)">{{ label(task.status) }}</el-tag><h2>{{ task.result?.speech_text||task.message||'商品讲解任务' }}</h2><el-progress :percentage="Number(task.progress||0)"/><p>{{ task.result?.marketing_use_case||'跨境商品数字人口播' }}</p></div></article></div><el-empty v-if="!loading&&!tasks.length" description="暂无数字人营销任务"><el-button type="primary" @click="router.push('/digital-human/create')">创建商品讲解人任务</el-button></el-empty></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{UserFilled}from'@element-plus/icons-vue';import{useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{digitalHumanAPI,type DigitalHumanTask}from'@/api/digital-human';const router=useRouter(),tasks=ref<DigitalHumanTask[]>([]),loading=ref(false),status=ref('');const label=(s:string)=>({pending:'等待中',processing:'处理中',completed:'已完成',failed:'失败'}[s]||s);const tone=(s:string)=>(s==='completed'?'success':s==='failed'?'danger':s==='processing'?'warning':'info');const load=async()=>{loading.value=true;try{tasks.value=(await digitalHumanAPI.getDigitalHumanTasks({page_size:50,status:status.value||undefined})).items||[]}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:24px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}.head .el-select{width:190px}.task-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:17px;min-height:120px}.task-grid article{overflow:hidden;border:1px solid var(--border-primary);border-radius:18px;background:var(--bg-card)}.task-grid video,.avatar{width:100%;height:180px;object-fit:cover;background:linear-gradient(135deg,#dbeafe,#ede9fe)}.avatar{display:grid;place-items:center;font-size:56px;color:var(--accent)}.task-grid article>div:last-child{padding:17px}.task-grid h2{font-size:17px;margin:11px 0}.task-grid p{margin-top:10px;color:var(--text-secondary)}</style>
